var n=`1230-tostones`;var a=`world-1230`;var i=`CU`;var s=`central-america-caribbean`;var r=4;var o=36;var l={en:`Tostones`,ua:`Тостонес`};var d={en:`Tostones is a dish from Cuba featuring plantain. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Тостонес, страва кухні країни Куба з такими основними складниками: плантан. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var u=[{en:`Peel green, firm plantains and cut into thick rounds; ripe sweet plantains do not give the same crisp tostones.`,ua:`Очистіть тверді зелені плантани та наріжте товстими кружальцями; стиглі солодкі плантани не дадуть таких хрустких тостонес.`,t:[`pressing`,`rolling-out-dough`],m:12,i:[[`plantain`,950,`g`]]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 9 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 9 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:9,i:[[`canola-oil`,850,`ml`]]},{en:`Flatten each par-fried plantain round gently between two clean flat surfaces, without breaking it apart.`,ua:`Обережно розплющте кожен напівготовий кружалець плантана між двома чистими пласкими поверхнями, не розламуючи.`,t:[`pressing-flat`],m:5,i:[]},{en:`Fry a second time at about 175°C until golden and crisp, then drain and salt immediately.`,ua:`Обсмажте вдруге приблизно при 175°C до золотистої хрусткої скоринки, обсушіть і одразу посоліть.`,t:[`deep-frying`],m:8,i:[]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:2,i:[[`table-salt`,null,`to_taste`],[`garlic-powder`,4,`g`]]}];var g={slug:n,id:a,country:`CU`,region:s,servings:4,minutes:36,title:l,text:d,steps:u};export{i as country,g as default,a as id,o as minutes,s as region,r as servings,n as slug,u as steps,d as text,l as title};